document.addEventListener("DOMContentLoaded",function(){const e=document.querySelector(".equipo-slider");if(!e)return;const n=e.querySelectorAll('input[name="equipo-slide"]');let t,o=0;function r(){o++,o>=n.length&&(o=0),n[o].checked=!0}function c(){t=setInterval(r,4500)}function d(){clearInterval(t)}c(),e.addEventListener("mouseenter",d),e.addEventListener("mouseleave",c),n.forEach((e,n)=>{e.addEventListener("change",()=>{o=n,d(),c()})})});